-- (a) Zero-copy clone of a database for testing (instant, no storage until modified)
CREATE DATABASE analytics_test CLONE analytics_prod;

-- (b) Time Travel: query a table as of 2 hours ago
SELECT *
FROM analytics_prod.public.orders
AT (OFFSET => -60*60*2);            -- 2 hours (7200 seconds) ago
-- Alternatively by absolute time:
-- ... AT (TIMESTAMP => '2024-06-15 08:00:00'::timestamp_tz);

-- (c) Secure data share of a filtered view to a partner account
CREATE SECURE VIEW analytics_prod.share_schema.partner_orders AS
    SELECT order_id, order_ts, amount
    FROM analytics_prod.public.orders
    WHERE partner_id = 'ACME';

CREATE SHARE acme_share;
GRANT USAGE  ON DATABASE analytics_prod              TO SHARE acme_share;
GRANT USAGE  ON SCHEMA   analytics_prod.share_schema TO SHARE acme_share;
GRANT SELECT ON VIEW analytics_prod.share_schema.partner_orders TO SHARE acme_share;
ALTER SHARE acme_share ADD ACCOUNTS = ACME_ACCOUNT_LOCATOR;
